pen wat het meisje is overkomen, groeit zijn twijfel over de mogelijke samenhang met zijn eigen onopgehelderde verleden.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/463579/de-offerplaats.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/463579/de-offerplaats.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"ffc0d02d62668541797f3529b58cf05ff2ca2023e8376fe5017616e0d2098125"}]}},{"relation":"editions","ref":"edition:9789044621853","key":{"id":976200125},"before":null,"after":{"work_id":924100673,"title":"Vijftig tinten donkerder","isbn_13":"9789044621853","isbn_10":null,"language":"nld","publisher":"Prometheus, Uitgeverij","open_library_edition_id":null,"id":976200125}},{"relation":"catalog_edition_metadata","ref":"metadata:9789044621853","key":{"edition_id":"@edition:9789044621853"},"before":null,"after":{"edition_id":"@edition:9789044621853","work_id":924100673,"bound_author_id":924300397,"bound_title":"Vijftig tinten donkerder","bound_language":"nld","bound_isbn13":"9789044621853","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000015516_Vijftig_tinten_donkerder_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/77043/vijftig-tinten-donkerder.html","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/77043/vijftig-tinten-donkerder.html","checkedAt":"2026-11-01","sha256":"ef61742285d78103ba62a79d60bc29d756904bf8ccaa71419788a6b19526984e","fact":"Exact title/author/ISBN, physical format and language source reviewed; independent contradictions recorded"},{"url":"https://metadata.isbn.nl/ie_fcache/0000015516_Vijftig_tinten_donkerder_0_0.jpg","checkedAt":"2026-11-01T10:57:06.166Z","sha256":"75e4b4f65a9afbbd16fe9e632d08ce9f1048b4aa54514d1f949b7195869dadf6","bytes":97514,"fact":"Same-edition source association and title/author artwork visually reviewed; not only HTTP200"}]}},{"relation":"catalog_work_descriptions","ref":"description:673","key":{"work_id":924100673,"language":"nl"},"before":null,"after":{"work_id":924100673,"language":"nl","bound_author_id":924300397,"text":"Anastasia Steele heeft haar verhouding met Christian Grey verbroken en probeert een eigen bestaan op te bouwen. Haar gevoelens voor hem verdwijnen daarmee niet. Wanneer hij opnieuw toenadering zoekt, moet ze bepalen onder welke voorwaarden zij hem kan vertrouwen. Ze ontdekt meer over zijn verleden en over relaties die nog altijd op hun leven inwerken. Hun poging opnieuw te beginnen brengt zo ook de grenzen en ongelijkheid tussen hen terug.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/77043/vijftig-tinten-donkerder.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/77043/vijftig-tinten-donkerder.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"ef61742285d78103ba62a79d60bc29d756904bf8ccaa71419788a6b19526984e"}]}},{"relation":"editions","ref":"edition:9789020552010","key":{"id":976200126},"before":null,"after":{"work_id":924100675,"title":"Things we never got over","isbn_13":"9789020552010","isbn_10":null,"language":"nld","publisher":"VBK Media","open_library_edition_id":null,"id":976200126}},{"relation":"catalog_edition_metadata","ref":"metadata:9789020552010","key":{"edition_id":"@edition:9789020552010"},"before":null,"after":{"edition_id":"@edition:9789020552010","work_id":924100675,"bound_author_id":924300399,"bound_title":"Things we never got over","bound_language":"nld","bound_isbn13":"9789020552010","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000538261_Things_we_never_got_over_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1667290/things-we-never-got-over.html","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1667290/things-we-never-got-over.html","checkedAt":"2026-11-01","sha256":"5bae593b7b0ccd820d1ab0f5e737d0519a645ac3646be3cf81d2ad8686d64f16","fact":"Exact title/author/ISBN, physical format and language source reviewed; independent contradictions recorded"},{"url":"https://metadata.isbn.nl/ie_fcache/0000538261_Things_we_never_got_over_0_0.jpg","checkedAt":"2026-11-01T10:57:07.949Z","sha256":"24cec77ca15b7bc11fea5cc8bf12e0c5f4688d09c63a746b0e418e25a70304d0","bytes":385873,"fact":"Same-edition source association and title/author artwork visually reviewed; not only HTTP200"}]}},{"relation":"catalog_work_descriptions","ref":"description:675","key":{"work_id":924100675,"language":"nl"},"before":null,"after":{"work_id":924100675,"language":"nl","bound_author_id":924300399,"text":"Naomi ontvlucht haar bruiloft en belandt vervolgens in de problemen die haar tweelingzus achterlaat. Zonder voorbereiding krijgt ze de zorg voor een nichtje dat ze nauwelijks kent. Knox wil zich niet met andermans chaos bemoeien, maar besluit haar toch te helpen. Wat als een tijdelijke oplossing bedoeld is, verandert hun dagelijkse leven. De roman volgt hoe zij omgaan met onverwachte verantwoordelijkheid en met de toenemende aantrekkingskracht tussen hen.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1667290/things-we-never-got-over.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1667290/things-we-never-got-over.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"5bae593b7b0ccd820d1ab0f5e737d0519a645ac3646be3cf81d2ad8686d64f16"}]}}]'::jsonb;receipt jsonb;r jsonb;p jsonb;k jsonb;expected jsonb;prior jsonb;ids jsonb:='{}';kv record;i integer:=0;n integer;begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'hlvujbrmfdlrfxdjwsmb' or receipt->>'batch' is distinct from 'nl005-03-20261101-test' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>30 then raise exception 'Exact manifest receipt required';end if;
 for p in select value from jsonb_array_elements(reviewed) loop
  i:=i+1;select count(*) into n from jsonb_array_elements(receipt->'rows')x where x->>'seq'=i::text;
  if n<>1 then raise exception 'Receipt manifest sequence mismatch';end if;
  select x into r from jsonb_array_elements(receipt->'rows')x where x->>'seq'=i::text;
  if r->>'relation' is distinct from p->>'relation' then raise exception 'Receipt manifest relation mismatch';end if;
  k:=p->'key';expected:=p->'after';prior:=p->'before';
  for kv in select * from jsonb_each(expected) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then
    if not ids ? substring(kv.value#>>'{}',2) then raise exception 'Receipt manifest missing parent';end if;
    expected:=jsonb_set(expected,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  for kv in select * from jsonb_each(k) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then k:=jsonb_set(k,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  if prior<>'null'::jsonb then execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',p->>'relation') into prior using prior;end if;
  execute format('select coalesce(jsonb_object_agg(x.key,x.value),''{}''::jsonb) from jsonb_each(to_jsonb(jsonb_populate_record(null::public.%I,$1))) x where $1 ? x.key',p->>'relation') into expected using expected;
  if r->'key' is distinct from k or r->'before_row' is distinct from prior or jsonb_typeof(r->'after_row') is distinct from 'object' or not coalesce((r->'after_row')@>expected,false) then raise exception 'Receipt differs from exact reviewed manifest';end if;
  if r->'after_row' ? 'id' then ids:=jsonb_set(ids,array[p->>'ref'],r->'after_row'->'id');end if;
 end loop;
end;$manifest_guard$;
do $undo$ declare receipt jsonb;r jsonb;actual jsonb;dep record;n bigint;cols text;begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'hlvujbrmfdlrfxdjwsmb' or receipt->>'batch' is distinct from 'nl005-03-20261101-test' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>30 then raise exception 'Exact first committed receipt required';end if;
 for r in select value from jsonb_array_elements(receipt->'rows') order by (value->>'seq')::integer desc loop
  if r->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed receipt relation';end if;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',r->>'relation') into actual using r->'key';
  if actual is null and r->'before_row'='null'::jsonb then continue;end if;
  if actual is not distinct from r->'before_row' then continue;end if;
  if actual is distinct from r->'after_row' then raise exception 'Later legitimate change; recovery refused';end if;
  if r->'before_row'='null'::jsonb then
   for dep in select ns.nspname,c.relname,string_agg(format('(to_jsonb(child)->%L)=($1->%L)',ca.attname,pa.attname),' and ' order by k.ord) predicate
    from pg_constraint f join pg_class c on c.oid=f.conrelid join pg_namespace ns on ns.oid=c.relnamespace
    cross join lateral unnest(f.conkey,f.confkey) with ordinality k(childkey,parentkey,ord)
    join pg_attribute ca on ca.attrelid=f.conrelid and ca.attnum=k.childkey join pg_attribute pa on pa.attrelid=f.confrelid and pa.attnum=k.parentkey
    where f.contype='f' and f.confrelid=to_regclass('public.'||(r->>'relation')) group by f.oid,ns.nspname,c.relname
   loop
    execute format('select count(*) from %I.%I child where %s',dep.nspname,dep.relname,dep.predicate) into n using r->'after_row';
    if n>0 then raise exception 'Later dependency in %.%; recovery refused',dep.nspname,dep.relname;end if;
   end loop;
   execute format('delete from public.%I t where to_jsonb(t) @> $1',r->>'relation') using r->'key';
  else
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,r->>'relation',key),',') into cols from jsonb_each(r->'before_row') where value is distinct from r->'after_row'->key;
   execute format('update public.%I t set %s where to_jsonb(t) @> $2',r->>'relation',cols) using r->'before_row',r->'key';
  end if;
 end loop;
end;$undo$;commit;
